formatter.$expression:
function (params) {
                    var date = new Date(params.value[0]);
                    return params.seriesName 
                           + ' （'
                           + date.getFullYear() + '-'
                           + (date.getMonth() + 1) + '-'
                           + date.getDate() + ' '
                           + date.getHours() + ':'
                           + date.getMinutes()
                           +  '）<br/>'
                           + params.value[1] + ', ' 
                           + params.value[2];
                }

